// === Tab: mySketch ===
/*
This is a submission for the #WCCChallenge theme of "earth"!
The majority of this sketch is done in a p5.strands shader. I've imported a Wikimedia
image of the continents, used just for land/water separation. The rest is done via the
shader to color the land and add clouds and lights.
*/

let mapImg
let globeShader
let atmosphere
let globe
let flat = false // Press a key to activate secret flat earth mode
async function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	pixelDensity(1)

	atmosphere = createFramebuffer({ antialias: false })
	globe = createFramebuffer({ antialias: false })

	mapImg = await loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
	globeShader = baseMaterialShader().modify(() => {
		const t = uniformFloat(() => millis() / 1000)
		const sign = (x) => {
			return smoothstep(0, 0.00001, x) * 2 - 1
		}
		getObjectInputs((inputs) => {
			inputs.texCoord.y = pow(abs(inputs.texCoord.y - 0.5), 1.3) * sign(inputs.texCoord.y - 0.5) + 0.5
			return inputs
		})
		getPixelInputs((inputs) => {
			const landType = clamp(abs(inputs.color.r - inputs.color.b), 0, 1)
			const theta = inputs.texCoord.y * Math.PI
			const phi = fract(inputs.texCoord.x + t * 0.005) * 2 * Math.PI
			const cloudCoord = [
				sin(theta) * cos(phi),
				sin(theta) * sin(phi),
				cos(theta)
			]
			const clouds = pow(clamp(
				0.1 * noise(
					noise(cloudCoord.xz * 4) * 10,
					noise(cloudCoord.zy * 4 + t * 0.05) * 10
				) + noise(
					noise(cloudCoord.xz + 50 + t * 0.05) * 5,
					noise(cloudCoord.zy + 50) * 5
				),
			0, 1), 0.8)
			const baseColor = mix(
				mix(
					color('#DCDBBC').array(),
					mix(
						mix(
							color('#4B8E56').array(),
							color('#90B482').array(),
							noise(
								noise(inputs.texCoord * 20) * 10,
								noise(inputs.texCoord * 20 + 100) * 30
							)
						),
						color('#FFFFFF').array(),
						smoothstep(0.1, 0.2, abs(inputs.texCoord.y - 0.5) - noise(inputs.texCoord * 100) * 0.1)
					),
					smoothstep(0.015, 0.05, abs(inputs.texCoord.y - 0.5) + noise(inputs.texCoord * 200) * 0.05)
				),
				color('#4429F9').array(),
				landType
			)

			inputs.emissiveMaterial = [1, 1, 0.8] * (1 - landType) * smoothstep(
				0.08,
				0.09,
				max(noise(inputs.texCoord * 15), noise(inputs.texCoord * 20)) * noise(inputs.texCoord * 500)
			) * (1 - smoothstep(0.75, 0.76, inputs.texCoord.y)) // no lights on antarctica please

			inputs.color = mix(
				baseColor,
				[1, 1, 1, 1],
				clouds
			)

			inputs.specularMaterial *= 0.8 * landType * (1 - clouds) + 0.2
			inputs.shininess *= 0.5 * landType * (1 - clouds) + 0.5

			return inputs
		})

		combineColors((components) => {
			return [
				components.diffuse * components.baseColor +
					components.ambient * components.ambientColor +
					components.specular * components.specularColor +
					// Only show lights when in shadow
					components.emissive * (1 - smoothstep(0, 0.1, components.diffuse)),
				components.opacity
			]
		})
	})
}

function draw() {
	background(0)
	imageMode(CENTER)

	const globeSize = max(width, height) * 0.35

	// The atmospheric haze is just a solid blue sphere on a blurred layer
	// below the earth
	atmosphere.draw(() => {
		background(0)
		orbitControl()
		push()
		directionalLight(255, 255, 255, -1, 0.1, -1)
		directionalLight(255, 255, 255, -1, 0.1, -1)
		directionalLight(255, 255, 255, 1, -0.1, 1)
		fill('#4792ED')
		flat ? circle(0, 0, globeSize * 2) : sphere(globeSize)
		pop()
		filter(BLUR, 25)
	})

	// The earth is just a sphere with a fun shader
	globe.draw(() => {
		clear()
		orbitControl()
		push()
		directionalLight(255, 255, 255, -1, 0.1, -1)
		!flat && rotateY(millis() * 0.0001 + PI/2)
		shader(globeShader)
		texture(mapImg)
		shininess(30)
		specularMaterial(200)
		noStroke()
		flat ? circle(0, 0, globeSize * 2) : sphere(globeSize, 60, 60)
		pop()
	})

	image(atmosphere, 0, 0)
	image(globe, 0, 0)
}

function keyPressed() {
	flat = !flat
}
